/**
 * Represents a student enrolled in the school, containing their personal information, contact details, medical information, and guardians.
 */
export interface Student {
    //! Basic Information
    /**
     * Required - Unique identifier for the student, generated by backend
     */
    id: string;
    /**
     * Required - Name(s) of the student
     */
    name: string;
    /**
     * Required - First last name of the student
     */
    firstLastName: string;
    /**
     * Optional - Second last name of the student
     */
    secondLastName: string;
    /**
     * Required - Date of birth as an ISO string (YYYY-MM-DDTHH:mm:ss.mmmZ)
     */
    dateOfBirth: string;
    /**
     * Required - Unique population registration number
     */
    curp: string;
    /**
     * Required - Unique enrollment number, generated by backend
     */
    enrollment: string;
    /**
     * Optional - URL to the student's image
     */
    image?: string;
    /**
     * Optional - Additional notes about the student
     */
    observations?: string;
    /**
     * Required - Indicates if the student is active
     */
    status: boolean;

    //! Contact Information
    /**
     * Required - Contact email for the student
     */
    email: string;
    /**
     * Required - Contact phone number for the student
     */
    phoneNumber: string;
    /**
     * Required - Full address as a single string
     */
    address: string;
    /**
     * Required - State or province
     */
    state: string;
    /**
     * Required - Municipality or city
     */
    municipality: string;
    /**
     * Required - Postal code
     */
    postalCode: string;
}
